import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except (TypeError, ValueError):
        return v is None


def _differs(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null or b_null:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim = inputs['DIM_CUSTOMER'].copy()
    stg = inputs['STG_CUSTOMER'].copy()

    if stg.empty:
        return {'dim_customer_out': dim}

    # Step 1: Deduplicate staging to latest record per customer_id by
    # update_date, tie-broken by greater (name, segment) lexicographically.
    stg_sorted = stg.sort_values(
        by=['customer_id', 'update_date', 'name', 'segment'],
        ascending=[True, False, False, False],
        kind='mergesort'
    )
    stg_dedup = stg_sorted.groupby('customer_id', as_index=False, sort=False).first()

    new_rows = []

    for _, s in stg_dedup.iterrows():
        cust_id = s['customer_id']
        mask_current = (dim['customer_id'] == cust_id) & (dim['is_current'] == 1)
        current_idxs = dim.index[mask_current]

        if len(current_idxs) == 0:
            # No current row exists -> insert new version
            new_rows.append({
                'customer_id': cust_id,
                'name': s['name'],
                'segment': s['segment'],
                'eff_start_date': s['update_date'],
                'eff_end_date': None,
                'is_current': 1
            })
        else:
            c = dim.loc[current_idxs[0]]
            name_diff = _differs(c['name'], s['name'])
            segment_diff = _differs(c['segment'], s['segment'])

            if name_diff or segment_diff:
                # Tracked-attribute change: expire existing current row(s)
                dim.loc[current_idxs, 'eff_end_date'] = s['update_date']
                dim.loc[current_idxs, 'is_current'] = 0

                new_rows.append({
                    'customer_id': cust_id,
                    'name': s['name'],
                    'segment': s['segment'],
                    'eff_start_date': s['update_date'],
                    'eff_end_date': None,
                    'is_current': 1
                })
            # else: no change -> do nothing, no new version created

    if new_rows:
        new_df = pd.DataFrame(new_rows, columns=dim.columns)
        dim = pd.concat([dim, new_df], ignore_index=True)

    return {'dim_customer_out': dim}
